using System.ComponentModel.DataAnnotations;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [Required, MaxLength(20)]
    public string TrackingNumber { get; set; } = "";

    [Required, MaxLength(200)]
    public string Origin { get; set; } = "";

    [Required, MaxLength(200)]
    public string Destination { get; set; } = "";

    public ShipmentStatus Status { get; set; }

    public DateTime EstimatedDelivery { get; set; }

    [Required, MaxLength(200)]
    public string CustomerName { get; set; } = "";

    [MaxLength(500)]
    public string Description { get; set; } = "";

    public DateTime CreatedAt { get; set; }
    public DateTime LastUpdated { get; set; }

    public ShipmentDto ToDto() => new()
    {
        Id = Id,
        TrackingNumber = TrackingNumber,
        Origin = Origin,
        Destination = Destination,
        Status = Status,
        EstimatedDelivery = EstimatedDelivery,
        CustomerName = CustomerName,
        Description = Description,
        CreatedAt = CreatedAt,
        LastUpdated = LastUpdated
    };
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetShipmentsAsync(string? statusFilter = null, string? searchTerm = null)
    {
        var query = db.Shipments.AsQueryable();

        if (!string.IsNullOrWhiteSpace(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, true, out var status))
        {
            query = query.Where(s => s.Status == status);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.ToLower();
            query = query.Where(s =>
                s.TrackingNumber.ToLower().Contains(term) ||
                s.Destination.ToLower().Contains(term) ||
                s.CustomerName.ToLower().Contains(term));
        }

        return await query.OrderByDescending(s => s.LastUpdated)
            .Select(s => s.ToDto())
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment?.ToDto();
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        var shipment = new Shipment
        {
            TrackingNumber = GenerateTrackingNumber(),
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = ShipmentStatus.Pending,
            EstimatedDelivery = dto.EstimatedDelivery,
            CustomerName = dto.CustomerName,
            Description = dto.Description,
            CreatedAt = DateTime.UtcNow,
            LastUpdated = DateTime.UtcNow
        };

        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return shipment.ToDto();
    }

    public async Task<ShipmentDto> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = await db.Shipments.FindAsync(id)
            ?? throw new KeyNotFoundException($"Shipment {id} not found");
        shipment.Status = status;
        shipment.LastUpdated = DateTime.UtcNow;
        await db.SaveChangesAsync();
        return shipment.ToDto();
    }

    private static string GenerateTrackingNumber()
    {
        return "ST-" + DateTime.UtcNow.ToString("yyyyMMdd") + "-" + Random.Shared.Next(10000, 99999);
    }
}

