@page "/"
@inject NavigationManager Nav

<PageTitle>ShipmentTracker – Track Your Shipment</PageTitle>

<div class="text-center py-5">
    <h1 class="display-5 fw-bold">Shipment Tracker</h1>
    <p class="lead text-muted mb-4">Track your shipment anywhere in the world</p>

    <div class="row justify-content-center">
        <div class="col-md-6">
            <div class="input-group input-group-lg">
                <input type="text" class="form-control" placeholder="Enter tracking number (e.g. ST-20260601-10001)"
                       @bind="trackingNumber" @bind:event="oninput"
                       @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
                    Track
                </button>
            </div>
        </div>
    </div>
</div>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card h-100">
            <div class="card-body text-center">
                <h5 class="card-title">📦 Real-Time Tracking</h5>
                <p class="card-text">Know exactly where your shipment is at any moment.</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card h-100">
            <div class="card-body text-center">
                <h5 class="card-title">🕒 Estimated Delivery</h5>
                <p class="card-text">Get accurate delivery estimates updated in real time.</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card h-100">
            <div class="card-body text-center">
                <h5 class="card-title">🌍 Worldwide Coverage</h5>
                <p class="card-text">Track shipments across the globe with low-latency access.</p>
            </div>
        </div>
    </div>
</div>

@code {
    private string trackingNumber = "";

    private void TrackShipment()
    {
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            Nav.NavigateTo($"track/{Uri.EscapeDataString(trackingNumber.Trim())}");
        }
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            TrackShipment();
    }
}

