@page "/track/{TrackingNumber}"
@inject ShipmentTracker.Client.Services.IShipmentService ShipmentService
@inject NavigationManager Nav

<PageTitle>Track Shipment – @TrackingNumber</PageTitle>

<h2>Shipment Tracking</h2>

@if (loading)
{
    <p><em>Loading...</em></p>
}
else if (shipment is null)
{
    <div class="alert alert-warning">
        <strong>Not found.</strong> No shipment matches tracking number <code>@TrackingNumber</code>.
    </div>
    <button class="btn btn-outline-primary" @onclick="@(() => Nav.NavigateTo("/"))">Try Again</button>
}
else
{
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@shipment.TrackingNumber</strong>
            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                        <dt>Description</dt>
                        <dd>@shipment.Description</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Customer</dt>
                        <dd>@shipment.CustomerName</dd>
                        <dt>Estimated Delivery</dt>
                        <dd>@shipment.EstimatedDelivery.ToString("MMMM d, yyyy")</dd>
                        <dt>Last Updated</dt>
                        <dd>@shipment.LastUpdated.ToString("g")</dd>
                    </dl>
                </div>
            </div>
        </div>
    </div>

    <h5>Shipment Progress</h5>
    <div class="progress mb-3" style="height: 30px;">
        <div class="progress-bar @GetProgressBarClass(shipment.Status)"
             role="progressbar"
             style="width: @(GetProgressPercent(shipment.Status))%"
             aria-valuenow="@GetProgressPercent(shipment.Status)"
             aria-valuemin="0" aria-valuemax="100">
            @shipment.Status
        </div>
    </div>

    <button class="btn btn-outline-primary" @onclick="Refresh">Refresh Status</button>
    <button class="btn btn-outline-secondary ms-2" @onclick="@(() => Nav.NavigateTo("/"))">Track Another</button>
}

@code {
    [Parameter] public string TrackingNumber { get; set; } = "";

    private ShipmentTracker.Client.Models.ShipmentDto? shipment;
    private bool loading = true;

    protected override async Task OnParametersSetAsync()
    {
        loading = true;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(TrackingNumber);
        loading = false;
    }

    private async Task Refresh()
    {
        loading = true;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(TrackingNumber);
        loading = false;
    }

    private static int GetProgressPercent(ShipmentTracker.Client.Models.ShipmentStatus status) => status switch
    {
        ShipmentTracker.Client.Models.ShipmentStatus.Pending => 10,
        ShipmentTracker.Client.Models.ShipmentStatus.PickedUp => 30,
        ShipmentTracker.Client.Models.ShipmentStatus.InTransit => 55,
        ShipmentTracker.Client.Models.ShipmentStatus.OutForDelivery => 80,
        ShipmentTracker.Client.Models.ShipmentStatus.Delivered => 100,
        ShipmentTracker.Client.Models.ShipmentStatus.Delayed => 55,
        ShipmentTracker.Client.Models.ShipmentStatus.Cancelled => 100,
        _ => 0
    };

    private static string GetProgressBarClass(ShipmentTracker.Client.Models.ShipmentStatus status) => status switch
    {
        ShipmentTracker.Client.Models.ShipmentStatus.Delivered => "bg-success",
        ShipmentTracker.Client.Models.ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentTracker.Client.Models.ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-primary"
    };

    private static string GetStatusBadgeClass(ShipmentTracker.Client.Models.ShipmentStatus status) => status switch
    {
        ShipmentTracker.Client.Models.ShipmentStatus.Delivered => "bg-success",
        ShipmentTracker.Client.Models.ShipmentStatus.Delayed => "bg-warning text-dark",
        ShipmentTracker.Client.Models.ShipmentStatus.Cancelled => "bg-danger",
        ShipmentTracker.Client.Models.ShipmentStatus.InTransit => "bg-info text-dark",
        ShipmentTracker.Client.Models.ShipmentStatus.OutForDelivery => "bg-primary",
        _ => "bg-secondary"
    };
}

@page "/shipments"
