+                    <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
+                </div>
+                <div class="col-md-4">
+                    <label class="form-label">Description</label>
+                    <input class="form-control" @bind="newShipment.Description" />
+                </div>
+            </div>
+            <div class="mt-3">
+                <button class="btn btn-primary" @onclick="CreateShipment" disabled="@creating">
+                    @(creating ? "Creating..." : "Create")
+                </button>
+                <button class="btn btn-outline-secondary ms-2" @onclick="@(() => showCreate = false)">Cancel</button>
+            </div>
+        </div>
+    </div>
+}
+
+@if (loading)
+{
+    <p><em>Loading shipments...</em></p>
+}
+else if (shipments.Count == 0)
+{
+    <div class="alert alert-info">No shipments found.</div>
+}
+else
+{
+    <div class="table-responsive">
+        <table class="table table-striped table-hover">
+            <thead class="table-dark">
+                <tr>
+                    <th>Tracking #</th>
+                    <th>Origin</th>
+                    <th>Destination</th>
+                    <th>Customer</th>
+                    <th>Status</th>
+                    <th>Est. Delivery</th>
+                    <th>Actions</th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var s in shipments)
+                {
+                    <tr>
+                        <td><code>@s.TrackingNumber</code></td>
+                        <td>@s.Origin</td>
+                        <td>@s.Destination</td>
+                        <td>@s.CustomerName</td>
+                        <td><span class="badge @GetBadgeClass(s.Status)">@s.Status</span></td>
+                        <td>@s.EstimatedDelivery.ToString("MMM d, yyyy")</td>
+                        <td>
+                            @if (editingId == s.Id)
+                            {
+                                <select class="form-select form-select-sm d-inline-block w-auto" @bind="newStatus">
+                                    @foreach (var st in Enum.GetValues<ShipmentStatus>())
+                                    {
+                                        <option value="@st">@st</option>
+                                    }
+                                </select>
+                                <button class="btn btn-sm btn-success ms-1" @onclick="@(() => SaveStatus(s.Id))">Save</button>
+                                <button class="btn btn-sm btn-outline-secondary ms-1" @onclick="@(() => editingId = null)">Cancel</button>
+                            }
+                            else
+                            {
+                                <button class="btn btn-sm btn-outline-primary" @onclick="@(() => StartEdit(s))">Update Status</button>
+                            }
+                        </td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    </div>
+}
+
+@code {
+    private List<ShipmentDto> shipments = [];
+    private bool loading = true;
+    private string searchTerm = "";
+    private string statusFilter = "";
+
+    private bool showCreate;
+    private bool creating;
+    private ShipmentDto newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
+
+    private int? editingId;
+    private ShipmentStatus newStatus;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadShipments();
+    }
+
+    private async Task LoadShipments()
+    {
+        loading = true;
+        shipments = await ShipmentService.GetShipmentsAsync(statusFilter, searchTerm);
+        loading = false;
+    }
+
+    private void HandleSearchKey(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter")
+            _ = LoadShipments();
+    }
+
+    private void ShowCreateForm()
+    {
+        newShipment = new ShipmentDto { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
+        showCreate = true;
+    }
+
+    private async Task CreateShipment()
+    {
+        creating = true;
+        await ShipmentService.CreateShipmentAsync(newShipment);
+        showCreate = false;
+        creating = false;
+        await LoadShipments();
+    }
+
+    private void StartEdit(ShipmentDto s)
+    {
+        editingId = s.Id;
+        newStatus = s.Status;
+    }
+
+    private async Task SaveStatus(int id)
+    {
+        await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
+        editingId = null;
+        await LoadShipments();
+    }
+
+    private static string GetBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Delayed => "bg-warning text-dark",
+        ShipmentStatus.Cancelled => "bg-danger",
+        ShipmentStatus.InTransit => "bg-info text-dark",
+        ShipmentStatus.OutForDelivery => "bg-primary",
+        _ => "bg-secondary"
+    };
+}
+
